local function C_5()
	local script = LMG2L["LocalScript_5"];
	local Players = game:GetService("Players")	
	local textbox = script.Parent.Parent.TextBox	
	script.Parent.MouseButton1Click:Connect(function()	
	for _, v in pairs(Players:GetPlayers()) do	
	    if v.Name:lower():sub(1,#textbox.Text) == textbox.Text:lower() then	
	        if not v.Character and v.Character:FindFirstChild("HumanoidRootPart") then return end	
	        local tchar = v.Character or v.CharacterAdded:Wait()	
	        local thrp = tchar.HumanoidRootPart or tchar:WaitForChild("HumanoidRootPart")	
	        local plr = Players.LocalPlayer	
	        local char = plr.Character or plr.CharacterAdded:Wait()	
	        local hum = char:FindFirstChildOfClass("Humanoid")	
	        hum:UnequipTools()	
	        local hrp = char.HumanoidRootPart or char:WaitForChild("HumanoidRootPart")	
	        local cam = workspace.CurrentCamera	
	        local oldcf = hrp.CFrame	
	        local clone = hum:Clone()	
	        clone.Parent = char	
	        hum:Destroy()	
	        clone:ChangeState("Dead")	
	        cam.CameraSubject = char	
	        local tool = plr.Backpack:FindFirstChildOfClass("Tool")	
	        clone:EquipTool(tool)	
	        local flag	
	        task.spawn(function()	
	        repeat	
	        thrp.CFrame = tool.Handle.CFrame	
	        task.wait()	
	        until flag	
	        end)	
	        tool.AncestryChanged:Wait()	
	        flag = true	
	        local newchar = plr.CharacterAdded:Wait()	
	        newchar:WaitForChild("HumanoidRootPart").CFrame = oldcf	
	end end end)	
end;
task.spawn(C_5);
